## Три API одной семьи

```javascript
function greet(greeting, name) {
  return `${greeting}, ${name} from ${this.label}`;
}
const ctx = { label: 'team' };

greet.call(ctx, 'Hi', 'Ann');   // аргументы списком
greet.apply(ctx, ['Hi', 'Ann']); // аргументы массивом
const bound = greet.bind(ctx, 'Hi');
bound('Bob'); // 'Hi, Bob from team'
```

**`bind`** также может **частично** применять аргументы (currying с фиксированным префиксом).

В практике ниже вы реализуете тонкие обёртки, делегирующие в нативные методы — чтобы закрепить контракт.

content.starterCode:
function invokeWithCall(fn, ctx, args) {
  return fn();
}

function demoCall() {
  const ctx = { base: 10 };
  function add(a, b) {
    return this.base + a + b;
  }
  return invokeWithCall(add, ctx, [1, 2]);
}

content.referenceSolution:
function invokeWithCall(fn, ctx, args) {
  return fn.call(ctx, ...args);
}

function demoCall() {
  const ctx = { base: 10 };
  function add(a, b) {
    return this.base + a + b;
  }
  return invokeWithCall(add, ctx, [1, 2]);
}

