function invokeWithApply(fn, ctx, args) {
  return fn.call(ctx);
}

function demoApply() {
  const ctx = { tag: 'id:' };
  function format(x) {
    return this.tag + x;
  }
  return invokeWithApply(format, ctx, [42]);
}

content.referenceSolution:
function invokeWithApply(fn, ctx, args) {
  return fn.apply(ctx, args);
}

function demoApply() {
  const ctx = { tag: 'id:' };
  function format(x) {
    return this.tag + x;
  }
  return invokeWithApply(format, ctx, [42]);
}

