## Отсоединённый метод

```javascript
const user = {
  name: 'Ann',
  hello() { return `Hi, ${this.name}`; },
};
const h = user.hello;
h(); // strict: TypeError или this без name
```

Классический фикс в React (до hooks): `this.onClick = this.onClick.bind(this)` в конструкторе.

**`bind`** возвращает функцию с навсегда привязанным `this` (и опционально частью аргументов).

content.starterCode:
function bindMethod(obj, methodName) {
  const fn = obj[methodName];
  return () => fn();
}

function demoBind() {
  const o = {
    n: 5,
    twice() {
      return this.n * 2;
    },
  };
  const t = bindMethod(o, 'twice');
  return t();
}

content.referenceSolution:
function bindMethod(obj, methodName) {
  const fn = obj[methodName];
  return fn.bind(obj);
}

function demoBind() {
  const o = {
    n: 5,
    twice() {
      return this.n * 2;
    },
  };
  const t = bindMethod(o, 'twice');
  return t();
}
